'use client';
import { useState, useEffect } from 'react';
import { FileUpload } from '@/components/FileUpload';
import { PasteInput } from '@/components/PasteInput';
import { ProgressBar } from '@/components/ProgressBar';
import { Button } from '@/components/ui/button';
import { Steps } from '@/components/Steps';
import { Download, CheckCircle, XCircle, AlertTriangle, Loader2, Play, ChevronLeft, RefreshCw } from 'lucide-react';
import axios from 'axios';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { motion, AnimatePresence } from 'framer-motion';

const WIZARD_STEPS = ['Input Data', 'Processing', 'Results'];

interface ValidationStats {
    total: number;
    processed: number;
    valid: number;
    invalid: number;
    risky: number;
}

export default function Dashboard() {
    const [currentStep, setCurrentStep] = useState(0);
    const [activeInputTab, setActiveInputTab] = useState<'upload' | 'paste'>('upload');

    const [jobId, setJobId] = useState<string | null>(null);
    const [status, setStatus] = useState<string>('idle');
    const [stats, setStats] = useState<ValidationStats>({ total: 0, processed: 0, valid: 0, invalid: 0, risky: 0 });
    const [results, setResults] = useState<any[]>([]);

    // Polling Effect
    useEffect(() => {
        let interval: NodeJS.Timeout;
        if (jobId && status !== 'completed' && status !== 'failed') {
            interval = setInterval(async () => {
                try {
                    const res = await axios.get(`http://localhost:3001/api/status/${jobId}`);
                    const data = res.data;
                    const newStatus = data.state;

                    if (newStatus === 'completed' && status !== 'completed') {
                        toast.success("Validation completed!");
                        setStatus('completed');
                        setCurrentStep(2); // Move to Results
                    } else if (newStatus === 'failed') {
                        toast.error("Validation failed.");
                        setStatus('failed');
                    } else {
                        setStatus(newStatus); // active, delayed...
                    }

                    if (data.result) {
                        const resList = data.result;
                        const valid = resList.filter((r: any) => r.status === 'valid').length;
                        const invalid = resList.filter((r: any) => r.status === 'invalid').length;
                        const risky = resList.filter((r: any) => r.status === 'risky').length;
                        setStats({ total: resList.length, processed: resList.length, valid, invalid, risky });
                        setResults(resList);
                    } else {
                        setStats(prev => ({ ...prev, processed: Math.floor((data.progress / 100) * prev.total) }));
                    }

                } catch (err) { console.error(err); }
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [jobId, status]);

    const handleStart = (id: string, total: number) => {
        setJobId(id);
        setStats({ total, processed: 0, valid: 0, invalid: 0, risky: 0 });
        setStatus('active');
        setCurrentStep(1); // Move to Processing
        toast.info("Started validation job...");
    };

    const handleReset = () => {
        setJobId(null);
        setStatus('idle');
        setResults([]);
        setCurrentStep(0);
        setStats({ total: 0, processed: 0, valid: 0, invalid: 0, risky: 0 });
    };

    const downloadReport = (type: 'valid' | 'invalid' | 'full') => {
        if (!results.length) return;
        let data = results;
        if (type === 'valid') data = results.filter(r => r.status === 'valid');
        if (type === 'invalid') data = results.filter(r => r.status === 'invalid');

        const csvContent = "data:text/csv;charset=utf-8,"
            + "Email,Status,Reason\n"
            + data.map(e => `${e.email},${e.status},${e.reason || ''}`).join("\n");
        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `email_report_${type}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const progress = stats.total > 0 ? Math.round((stats.processed / stats.total) * 100) : 0;

    return (
        <div className="max-w-4xl mx-auto py-8">
            <Steps steps={WIZARD_STEPS} currentStep={currentStep} />

            <AnimatePresence mode='wait'>
                {/* STEP 1: INPUT */}
                {currentStep === 0 && (
                    <motion.div
                        key="step-input"
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden"
                    >
                        <div className="flex border-b border-slate-200">
                            <button onClick={() => setActiveInputTab('upload')} className={cn("flex-1 py-4 text-sm font-medium transition-colors", activeInputTab === 'upload' ? "text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50" : "text-slate-500 hover:bg-slate-50")}>
                                Upload File
                            </button>
                            <button onClick={() => setActiveInputTab('paste')} className={cn("flex-1 py-4 text-sm font-medium transition-colors", activeInputTab === 'paste' ? "text-indigo-600 border-b-2 border-indigo-600 bg-indigo-50/50" : "text-slate-500 hover:bg-slate-50")}>
                                Paste Text
                            </button>
                        </div>
                        <div className="p-10">
                            <h2 className="text-2xl font-bold text-center mb-2 text-slate-800">Add Your Emails</h2>
                            <p className="text-center text-slate-500 mb-8">We'll clean your list in seconds.</p>

                            {activeInputTab === 'upload' ? (
                                <FileUpload onUploadStart={handleStart} onError={msg => toast.error(msg)} />
                            ) : (
                                <PasteInput onUploadStart={handleStart} onError={msg => toast.error(msg)} />
                            )}
                        </div>
                    </motion.div>
                )}

                {/* STEP 2: PROCESSING */}
                {currentStep === 1 && (
                    <motion.div
                        key="step-process"
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 1.05 }}
                        className="bg-white rounded-2xl shadow-lg border border-indigo-100 p-10 text-center"
                    >
                        <div className="mb-8">
                            <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-4 relative">
                                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
                                <div className="absolute inset-0 rounded-full border-4 border-indigo-100 border-t-indigo-600 animate-spin" />
                            </div>
                            <h2 className="text-2xl font-bold text-slate-800">Validating {stats.total} Emails</h2>
                            <p className="text-slate-500 mt-2">Checking syntax, domains, and mailboxes...</p>
                        </div>

                        <ProgressBar progress={progress} />

                        <div className="grid grid-cols-4 gap-4 mt-10 max-w-2xl mx-auto">
                            <StatBox label="Valid" value={stats.valid} className="bg-green-50 text-green-700" />
                            <StatBox label="Invalid" value={stats.invalid} className="bg-red-50 text-red-700" />
                            <StatBox label="Risky" value={stats.risky} className="bg-yellow-50 text-yellow-700" />
                            <StatBox label="Remaining" value={stats.total - stats.processed} className="bg-slate-50 text-slate-600" />
                        </div>
                    </motion.div>
                )}

                {/* STEP 3: RESULTS */}
                {currentStep === 2 && (
                    <motion.div
                        key="step-results"
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="space-y-6"
                    >
                        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8">
                            <div className="flex items-center gap-4 mb-8">
                                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                                    <CheckCircle className="w-6 h-6" />
                                </div>
                                <div>
                                    <h2 className="text-2xl font-bold text-slate-800">Validation Complete!</h2>
                                    <p className="text-slate-500">Here's the breakdown of your list.</p>
                                </div>
                                <Button variant="outline" className="ml-auto" onClick={handleReset}>
                                    <RefreshCw className="w-4 h-4 mr-2" /> Start Over
                                </Button>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                                <ResultCard title="Valid Emails" count={stats.valid} color="green" percent={stats.total > 0 ? ((stats.valid / stats.total) * 100).toFixed(1) : "0.0"} />
                                <ResultCard title="Invalid Emails" count={stats.invalid} color="red" percent={stats.total > 0 ? ((stats.invalid / stats.total) * 100).toFixed(1) : "0.0"} />
                                <ResultCard title="Risky/Unknown" count={stats.risky} color="yellow" percent={stats.total > 0 ? ((stats.risky / stats.total) * 100).toFixed(1) : "0.0"} />
                            </div>

                            <div className="bg-slate-50 rounded-xl p-6 flex flex-col sm:flex-row items-center justify-between gap-4">
                                <div className="text-sm text-slate-500 font-medium">Download Reports</div>
                                <div className="flex gap-3">
                                    <Button onClick={() => downloadReport('valid')} className="bg-green-600 hover:bg-green-700 text-white">
                                        <Download className="w-4 h-4 mr-2" /> Valid Only
                                    </Button>
                                    <Button onClick={() => downloadReport('invalid')} variant="destructive" className="bg-red-500 hover:bg-red-600">
                                        Invalid Only
                                    </Button>
                                    <Button onClick={() => downloadReport('full')} variant="outline">
                                        Full CSV
                                    </Button>
                                </div>
                            </div>
                        </div>

                        <ResultsTable results={results} />
                    </motion.div>
                )}
            </AnimatePresence>
        </div >
    );
}

function StatBox({ label, value, className }: any) {
    return (
        <div className={cn("p-4 rounded-xl text-center", className)}>
            <div className="text-2xl font-bold mb-1">{value}</div>
            <div className="text-xs uppercase font-semibold opacity-70">{label}</div>
        </div>
    )
}

function ResultCard({ title, count, color, percent }: any) {
    const colors: any = {
        green: "bg-green-50 text-green-700 border-green-100",
        red: "bg-red-50 text-red-700 border-red-100",
        yellow: "bg-yellow-50 text-yellow-700 border-yellow-100"
    };

    return (
        <div className={cn("p-6 rounded-xl border flex flex-col", colors[color])}>
            <div className="text-sm font-semibold opacity-80 mb-2">{title}</div>
            <div className="text-4xl font-bold mb-2">{count}</div>
            <div className="text-sm font-medium bg-white/50 w-fit px-2 py-1 rounded inline-block">
                {percent}% of total
            </div>
        </div>
    )
}
